(function(){'use strict';var popup = document.getElementById('chatPopup');var floatBtn = document.getElementById('aiFloatBtn');var chatBody = document.getElementById('chatBody');var chatInput = document.getElementById('chatInput');var isOpen = false;var lang = 'en';window.toggleChat = function(){isOpen = !isOpen;if(popup)popup.classList.toggle('open',isOpen);if(floatBtn)floatBtn.style.display = isOpen ? 'none':'flex';};window.toggleChatLanguage = function(){lang =(lang === 'en')? 'hi':'en';var btn = document.getElementById('langToggle');if(btn)btn.textContent = lang === 'hi' ? '\u{1F1EE}\u{1F1F3}EN':'\u{1F1EE}\u{1F1F3}HI';};window.sendChatMessage = function(){if(!chatInput)return;var msg = chatInput.value.trim();if(!msg)return;chatInput.value = '';appendMessage(msg,'user');getBotResponse(msg);};window.handleChatKeypress = function(e){if(e.key === 'Enter')sendChatMessage();};window.sendQuickMessage = function(msg){appendMessage(msg,'user');getBotResponse(msg);if(!isOpen)toggleChat();};function appendMessage(text,sender){if(!chatBody)return;var div = document.createElement('div');div.className = 'ai-message ' + sender;div.innerHTML = '<div class="ai-message-content">' + escapeHtml(text)+ '</div>' + '<span class="ai-time">Just now</span>';chatBody.appendChild(div);chatBody.scrollTop = chatBody.scrollHeight;}function getBotResponse(userMsg){var typingDiv = document.createElement('div');typingDiv.className = 'ai-message bot';typingDiv.innerHTML = '<div class="ai-message-content"><em>Typing...</em></div>';if(chatBody)chatBody.appendChild(typingDiv);var apiUrl = window.chatbotApiUrl || window.location.origin + '/api/ai/chat';var context = window.chatbotUserContext ||{};fetch(apiUrl,{method:'POST',headers:{'Content-Type':'application/json','X-Requested-With':'XMLHttpRequest'},body:JSON.stringify({message:userMsg,language:lang,context:context})}).then(function(r){return r.json();}).then(function(data){typingDiv.remove();var reply = data.response || data.reply || data.message || 'Sorry,I didn\'t understand. Please try again.';appendMessage(reply,'bot');}).catch(function(){typingDiv.remove();appendMessage('Namaste! \u{1F91D}Welcome to APS Dream Home! How can I help you today?','bot');});}function escapeHtml(text){var div = document.createElement('div');div.appendChild(document.createTextNode(text));return div.innerHTML;}if(!sessionStorage.getItem('chatbot_shown')){setTimeout(function(){if(!isOpen && floatBtn){floatBtn.style.animation = 'pulse-ring 1.5s ease 3';setTimeout(function(){floatBtn.style.animation = '';},4500);}sessionStorage.setItem('chatbot_shown','1');},5000);}})();